package equalizer

import (
	"crypto/sha256"
	"encoding/binary"
	"fmt"
	"math"
	"testing"
)

func TestWebsiteGraphMatchesKuba(t *testing.T) {
	// Reference digests were generated by running Kuba's deployed resultCurve
	// and targetCurve functions offline on their original 280-point grid.
	wantDigests := map[string]string{
		"padrao":     "ceee71334080f024148198452a38b966d3faf0b16bb4f2973f1d7c00e163d702",
		"pref6":      "9cf6a549c1d2091133a6936fd1f7dc44215490c074be964f8aa261882e935d76",
		"emv":        "8e9f2fa3e74d4aa3120b279bd964869bc5cb46036f6f87b1961bb6c6285505df",
		"basshead":   "ce06fcfd6370608d13654e7b4c4e864527ce9f605fea41f4a8f4c81bbde93d9b",
		"energico":   "e4ae16b3d2a190733d30b69c240ccf252aeb325d687a7cb492d5f745b7cc7f20",
		"musical":    "d0d84514f0b23d96d42cdda1b4fcb9a1bdd5a9a5b34ac4d64c9482d617b75237",
		"analitico":  "e03e062d81f5378819b3ecf8255552b820daf20af22c7560154fc5b6201008ac",
		"referencia": "51c5016f20b2c628848cdd6adfc2daf07b784fea61b88ebf7f0c8a0896fe3f5b",
		"harman":     "98315bf0b52b527114c505aade51b11a7e2c70de24f5af45faedeab2e1946991",
		"vdsf":       "4f89df938b6489996667ca22c89563b7c676d860c35fbc5758b97d3d9c109dff",
		"etymotic":   "7cfd18c89bc41fef87b822563a143eeae14fd1c653eb65754968177f4a332c0e",
	}
	views := (&App{}).Presets()
	if len(views) != len(wantDigests) {
		t.Fatalf("got %d presets, want %d", len(views), len(wantDigests))
	}
	for _, view := range views {
		want, ok := wantDigests[view.ID]
		if !ok {
			t.Errorf("unexpected or duplicate preset %q", view.ID)
			continue
		}
		delete(wantDigests, view.ID)
		t.Run(view.ID, func(t *testing.T) {
			wantTarget := "JM-1"
			if view.ID == "harman" {
				wantTarget = "Harman IE 2019"
			}
			if view.TargetName != wantTarget {
				t.Errorf("got target %q, want %q", view.TargetName, wantTarget)
			}
			const samples = 280
			if len(view.Curve) != samples || len(view.Target) != samples {
				t.Fatalf("got %d response samples and %d target samples, want %d each", len(view.Curve), len(view.Target), samples)
			}
			// Each row is (hundredths of Hz, response and target at 1e-5 dB),
			// rounded to signed little-endian integers to allow minor libm drift.
			data := make([]byte, 0, samples*12)
			for i, point := range view.Curve {
				target := view.Target[i]
				if target.Frequency != point.Frequency {
					t.Fatalf("sample %d: response at %g Hz, target at %g Hz", i, point.Frequency, target.Frequency)
				}
				data = binary.LittleEndian.AppendUint32(data, uint32(int32(math.Round(point.Frequency*100))))
				data = binary.LittleEndian.AppendUint32(data, uint32(int32(math.Round(point.DB*100_000))))
				data = binary.LittleEndian.AppendUint32(data, uint32(int32(math.Round(target.DB*100_000))))
			}
			if got := fmt.Sprintf("%x", sha256.Sum256(data)); got != want {
				t.Errorf("graph digest = %s, want %s", got, want)
			}
		})
	}
}
